#include <iostream>
#include <vector>
#include <algorithm>

const int SIZE = 3;

void sortRows(const double m[][SIZE], double result[][SIZE]) {
    for (int i = 0; i < SIZE; ++i) {
        for (int j = 0; j < SIZE; ++j) {
            result[i][j] = m[i][j];
        }
        std::sort(result[i], result[i] + SIZE);
    }
}

bool strictlyIdentical(const int m1[][SIZE], const int m2[][SIZE]) {
    for (int i = 0; i < SIZE; ++i) {
        for (int j = 0; j < SIZE; ++j) {
            if (m1[i][j] != m2[i][j]) return false;
        }
    }
    return true;
}

bool identicalContents(const int m1[][SIZE], const int m2[][SIZE]) {
    std::vector<int> v1, v2;
    v1.reserve(SIZE * SIZE);
    v2.reserve(SIZE * SIZE);
    for (int i = 0; i < SIZE; ++i) {
        for (int j = 0; j < SIZE; ++j) {
            v1.push_back(m1[i][j]);
            v2.push_back(m2[i][j]);
        }
    }
    std::sort(v1.begin(), v1.end());
    std::sort(v2.begin(), v2.end());
    return v1 == v2;
}

int main() {
    int a[SIZE][SIZE] = {{51, 25, 22}, {6, 1, 4}, {24, 54, 6}};
    int b[SIZE][SIZE] = {{51, 22, 25}, {6, 1, 4}, {24, 54, 6}};

    std::cout << "Strictly identical: " << (strictlyIdentical(a, b) ? "true" : "false") << "\n";
    std::cout << "Identical contents: " << (identicalContents(a, b) ? "true" : "false") << "\n";
    return 0;
}

#include <iostream>
#include <cmath>

const int SIZE = 2;

bool linearEquation(const double a[][SIZE], const double b[], double result[]) {
    double det = a[0][0] * a[1][1] - a[0][1] * a[1][0];
    if (std::abs(det) < 1e-9) {
        return false;
    }
    result[0] = (b[0] * a[1][1] - b[1] * a[0][1]) / det;
    result[1] = (b[1] * a[0][0] - b[0] * a[1][0]) / det;
    return true;
}

int main() {
    double a[2][2] = {{2.0, 1.0}, {1.0, -1.0}};
    double b[2] = {5.0, 1.0};
    double result[2];

    if (linearEquation(a, b, result)) {
        std::cout << "x = " << result[0] << ", y = " << result[1] << "\n";
    } else {
        std::cout << "The equation has no solution\n";
    }
    return 0;
}
